// 1. Capturamos la entrada del nodo que haya ejecutado exitosamente
const inputData = $input.first().json;
let textoIA = "";

// 2. Evaluamos dinámicamente de qué modelo viene la respuesta
if (inputData?.content?.parts?.[0]?.text) {
    // Estructura de Gemini
    textoIA = inputData.content.parts[0].text;
} 
else if (inputData?.output?.[0]?.content?.[0]?.text) {
    // Estructura del segundo modelo 
    textoIA = inputData.output[0].content[0].text;
} 
else if (inputData?.choices?.[0]?.message?.content) {
    // Estructura estándar de OpenAI (por si en el futuro cambiamos el nodo a OpenAI puro)
    textoIA = inputData.choices[0].message.content;
}

// 3. Procesamos el texto limpiando el Markdown
try {
  // Si por alguna razón la IA devolvió algo raro y no hay texto, forzamos el catch
  if (!textoIA) throw new Error("No se encontró el texto en la estructura del JSON");

  // Limpieza de etiquetas markdown (```json y ```)
  const limpio = textoIA.replace(/```json/g, '').replace(/```/g, '').trim();

  // Parseo a JSON puro
  const receta = JSON.parse(limpio);
  return receta;

} catch (e) {
  // 4. Fallback si el parseo falla o si el texto vino vacío
  return {
    nombre: "Receta no disponible",
    ingredientes: ["No pudimos generar la receta en este momento"],
    pasos: ["Por favor intenta de nuevo en unos segundos"]
  };
}

// Este nodo recibe el payload del Webhook con los datos del producto ya
// elegido por el React, y arma el prompt que le vamos a pasar a Gemini.
// No filtra nada, no decide nada. Solo transforma datos en un prompt.

const datos = $json.body;

// Validación defensiva: si faltan campos críticos, fallamos temprano con un
// mensaje claro en vez de mandar un prompt roto a Gemini.
if (!datos.producto || !datos.preparacion_elegida || !datos.personas) {
  throw new Error('Faltan campos obligatorios en el payload: producto, preparacion_elegida o personas.');
}

// Armado del prompt. Es crítico que el prompt pida JSON estricto y que los
// límites de cinco ingredientes y cuatro pasos estén explícitos, porque los
// LLMs tienden a excederse si solo se les pide "máximo X" sin reforzar.
const prompt = `Eres un chef profesional colombiano. Vas a generar una receta en formato JSON estricto.

Producto: ${datos.producto}
Descripcion: ${datos.descripcion || 'No disponible'}
Presentacion: ${datos.presentacion || 'No disponible'}
Metodo de coccion: ${datos.preparacion_elegida}
Numero de personas: ${datos.personas}
Marca: ${datos.marca}

Instrucciones obligatorias:
- Responde UNICAMENTE con JSON valido, sin texto adicional antes ni despues.
- La receta debe tener EXACTAMENTE 5 ingredientes o menos, nunca mas de 5.
- La receta debe tener EXACTAMENTE 4 pasos de preparacion o menos, nunca mas de 4.
- Cada paso debe ser una oracion corta y clara, maximo 20 palabras.
- Los ingredientes deben estar en cantidades ajustadas para ${datos.personas} personas.
- El nombre de la receta debe ser breve, maximo 8 palabras y conservar el nombre del producto: ${datos.producto} y el método de cocción ${datos.preparacion_elegida}.
- El primer ingrediente DEBE incluir la marca "${datos.marca}" junto al nombre del producto. Ejemplo: "1 kg alitas de pollo FRIKO" o "600g Brochetas de langostino ANTILLANA".

### EJEMPLOS DE REFERENCIA (FEW-SHOT):

Ejemplo 1:
Entrada: { "producto": "Brochetas de langostino", "descripcion": "Langostino en pincho", "presentacion": 6 und / 600 g, "metodo": "Parrilla", "personas": 4 }
Salida: {
  "nombre": "Brochetas de langostino a la parrilla con ajo",
  "ingredientes": ["600g Brochetas de langostino ANTILLANA", "2 dientes de ajo picados", "2 cucharadas de aceite de oliva", "1 limón", "Perejil fresco picado"],
  "preparación": [
    "Marina los langostinos con ajo, aceite y limón.",
    "Ensarta los langostinos ANTILLANA en las brochetas",
    "Cocina a la parrilla por 3-4 minutos por lado.",
    "Sirve con perejil fresco picado."
  ]
}

Ejemplo 2:
Entrada: { "producto": "Alitas BBQ", "descripcion": "Alitas marinadas BBQ", "ocasion": "HOGAR", "metodo": "Horno", "personas": 4 }
Salida: {
  "nombre": "Alitas BBQ Colombianas al horno",
  "ingredientes": ["1 kg alitas de pollo FRIKO", "150 ml salsa BBQ", "2 cucharadas de miel", "1 cucharadita pimentón ahumado", "Sal y pimienta al gusto"],
  "preparación": [
    "Marinar las alitas con salsa BBQ, miel y especias.",
    " Precalentar el horno a 180°C (350°F).",
    "Hornear las alitas durante 30-40 min.",
    "Servir calientes y disfrutar."
  ]
}

Formato de respuesta obligatorio (JSON puro, sin markdown, sin backticks):
{
  "nombre": "Nombre corto de la receta",
  "ingredientes": ["ingrediente 1", "ingrediente 2", "ingrediente 3", "ingrediente 4", "ingrediente 5"],
  "pasos": ["paso 1", "paso 2", "paso 3", "paso 4"]
}`;


return {
  prompt: prompt,
  producto_nombre: datos.producto
};

